; mandelbrot.asm - generated by gen_mandelbrot.py, do not edit by hand
; Placard CPU: the Mandelbrot set drawn in 1, 2, 4 and 8 bpp in turn,
; 32 iterations, 8 fraction bits.  See gen_mandelbrot.py for the method
; and memory map.
;     repeats forever, about 5 s pause after each mode
;
;     python3 placard_sim.py mandelbrot.asm --run --max-steps 2000000000 --png m.png
;
; Date: 10/22/2026

#include "placard.asm"

#addr 0x0000
reset:
    ld   main >> 8, y
    jmp  main

#addr 0x0080
font:      ; 0-9, ".", space, "s"; 8 bytes each, leftmost pixel in bit 0
    #d8 0x0E, 0x11, 0x19, 0x15, 0x13, 0x11, 0x0E, 0x00
    #d8 0x04, 0x06, 0x04, 0x04, 0x04, 0x04, 0x0E, 0x00
    #d8 0x0E, 0x11, 0x10, 0x08, 0x04, 0x02, 0x1F, 0x00
    #d8 0x1F, 0x08, 0x04, 0x08, 0x10, 0x11, 0x0E, 0x00
    #d8 0x08, 0x0C, 0x0A, 0x09, 0x1F, 0x08, 0x08, 0x00
    #d8 0x1F, 0x01, 0x0F, 0x10, 0x10, 0x11, 0x0E, 0x00
    #d8 0x0C, 0x02, 0x01, 0x0F, 0x11, 0x11, 0x0E, 0x00
    #d8 0x1F, 0x10, 0x08, 0x04, 0x02, 0x02, 0x02, 0x00
    #d8 0x0E, 0x11, 0x11, 0x0E, 0x11, 0x11, 0x0E, 0x00
    #d8 0x0E, 0x11, 0x11, 0x1E, 0x10, 0x08, 0x06, 0x00
    #d8 0x00, 0x00, 0x00, 0x00, 0x00, 0x06, 0x06, 0x00
    #d8 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    #d8 0x00, 0x00, 0x1E, 0x01, 0x0E, 0x10, 0x0F, 0x00

#addr 0x0100
main:
    ; ---- pass 0: 1 bpp ----
    ld   0x80, ac
    ld   ac, [0x37]
    ld   ret_1, ac
    ld   ac, [0x2C]
    ld   ret_1 >> 8, ac
    ld   ac, [0x2D]
    ld   pass0 >> 8, y
    jmp  pass0
ret_1:
    ld   ret_2, ac
    ld   ac, [0x2C]
    ld   ret_2 >> 8, ac
    ld   ac, [0x2D]
    ld   tshow >> 8, y
    jmp  tshow
ret_2:
    ld   ret_3, ac
    ld   ac, [0x2C]
    ld   ret_3 >> 8, ac
    ld   ac, [0x2D]
    ld   delay >> 8, y
    jmp  delay
ret_3:
    ; ---- pass 1: 2 bpp ----
    ld   0x81, ac
    ld   ac, [0x37]
    ld   ret_4, ac
    ld   ac, [0x2C]
    ld   ret_4 >> 8, ac
    ld   ac, [0x2D]
    ld   pass1 >> 8, y
    jmp  pass1
ret_4:
    ld   ret_5, ac
    ld   ac, [0x2C]
    ld   ret_5 >> 8, ac
    ld   ac, [0x2D]
    ld   tshow >> 8, y
    jmp  tshow
ret_5:
    ld   ret_6, ac
    ld   ac, [0x2C]
    ld   ret_6 >> 8, ac
    ld   ac, [0x2D]
    ld   delay >> 8, y
    jmp  delay
ret_6:
    ; ---- pass 2: 4 bpp ----
    ld   0x82, ac
    ld   ac, [0x37]
    ld   ret_7, ac
    ld   ac, [0x2C]
    ld   ret_7 >> 8, ac
    ld   ac, [0x2D]
    ld   pass2 >> 8, y
    jmp  pass2
ret_7:
    ld   ret_8, ac
    ld   ac, [0x2C]
    ld   ret_8 >> 8, ac
    ld   ac, [0x2D]
    ld   tshow >> 8, y
    jmp  tshow
ret_8:
    ld   ret_9, ac
    ld   ac, [0x2C]
    ld   ret_9 >> 8, ac
    ld   ac, [0x2D]
    ld   delay >> 8, y
    jmp  delay
ret_9:
    ; ---- pass 3: 8 bpp ----
    ld   0x83, ac
    ld   ac, [0x37]
    ld   ret_10, ac
    ld   ac, [0x2C]
    ld   ret_10 >> 8, ac
    ld   ac, [0x2D]
    ld   pass3 >> 8, y
    jmp  pass3
ret_10:
    ld   ret_11, ac
    ld   ac, [0x2C]
    ld   ret_11 >> 8, ac
    ld   ac, [0x2D]
    ld   tshow >> 8, y
    jmp  tshow
ret_11:
    ld   ret_12, ac
    ld   ac, [0x2C]
    ld   ret_12 >> 8, ac
    ld   ac, [0x2D]
    ld   delay >> 8, y
    jmp  delay
ret_12:
    ; done: the menu goes on to the next program now (when rotating)
    ld   ret_13, ac
    ld   ac, [0xE8]
    ld   ret_13 >> 8, ac
    ld   ac, [0xE9]
    ld   hk_done >> 8, y
    jmp  hk_done
ret_13:
    ld   main >> 8, y
    jmp  main

#addr 0x0200
clear:
    ; video RAM 6000-FFFF = 0, then mode byte = [mode] | 80 (blanked) for rows
    ; 5A20-5BFF
    ld   0x60, ac
    ld   ac, [0x38]
clr_pg:
    ld   [0x38], y
    clr  ac
clr_b:
    ld   ac, x
    ld   0x00, [y,x]
    inc
    bne  clr_b
    ld   [0x38], ac
    inc
    ld   ac, [0x38]
    bne  clr_pg
    ld   0x5A, y
    ld   0x20, ac
mode0:
    ld   ac, x
    ld   ac, [0x38]
    ld   [0x37], ac
    ld   ac, [y,x]
    ld   [0x38], ac
    inc
    bne  mode0
    ld   0x5B, y
mode1:
    ld   ac, x
    ld   ac, [0x38]
    ld   [0x37], ac
    ld   ac, [y,x]
    ld   [0x38], ac
    inc
    bne  mode1
    ld   [0x2D], y
    jmp  [0x2C]

#addr 0x0300
delay:
    ; about 5 s at 25.175 MHz, less the video stalls
    ld   0xC1, ac
    ld   ac, [0x3A]
dly3:
    ld   0x00, ac
    ld   ac, [0x39]
dly2:
    ld   ret_14, ac
    ld   ac, [0xE8]
    ld   ret_14 >> 8, ac
    ld   ac, [0xE9]
    ld   hk_poll >> 8, y
    jmp  hk_poll
ret_14:
    clr  ac
dly1:
    nop
    dec
    bne  dly1
    ld   [0x39], ac
    dec
    ld   ac, [0x39]
    bne  dly2
    ld   [0x3A], ac
    dec
    ld   ac, [0x3A]
    bne  dly3
    ld   [0x2D], y
    jmp  [0x2C]

#addr 0x0400
pass0:
    ; 1 bpp: 8 points per byte, 1 x 1 pixels per point
    ld   [0x2C], ac
    ld   ac, [0x3B]
    ld   [0x2D], ac
    ld   ac, [0x3C]
    ld   ret_15, ac
    ld   ac, [0x2C]
    ld   ret_15 >> 8, ac
    ld   ac, [0x2D]
    ld   clear >> 8, y
    jmp  clear
ret_15:
    ld   ret_16, ac
    ld   ac, [0x2C]
    ld   ret_16 >> 8, ac
    ld   ac, [0x2D]
    ld   tstart >> 8, y
    jmp  tstart
ret_16:
    ld   0x00, ac
    ld   ac, [0x2B]
    ; row by row, top to bottom: every row starts blanked (clear) and
    ; is shown when its points are done, so the video does not stall
    ; the CPU on the rows still to come
    ld   0x20, ac
    ld   ac, [0x33]
    ld   0x00, ac
    ld   ac, [0x34]
    ; cy = -240/256 = (hi -1, lo 16)
    ld   0xFF, ac
    ld   ac, [0x29]
    ld   0x10, ac
    ld   ac, [0x28]
row0:
    ld   0x62, ac
    ld   ac, [0x35]
    ; cx = -2.0 = -512 = (hi -2, lo 0)
    ld   0xFE, ac
    ld   ac, [0x2F]
    ld   0x00, ac
    ld   ac, [0x2E]
    ld   0x4F, ac
    ld   ac, [0x36]
col0:
    ld   [0x2E], ac
    ld   ac, [0x26]
    ld   [0x2F], ac
    ld   ac, [0x27]
    ld   0x00, ac
    ld   ac, [0x30]
    ld   0x08, ac
    ld   ac, [0x32]
pt0:
    ld   ret_17, ac
    ld   ac, [0x2C]
    ld   ret_17 >> 8, ac
    ld   ac, [0x2D]
    ld   kernel >> 8, y
    jmp  kernel
ret_17:
    ld   ac, [0x31]
    ld   [0x30], ac
    shr  ac
    or   [0x31], ac
    ld   ac, [0x30]
    ; next point: cx lo is a multiple of 8 plus < 8, never carries
    ld   [0x26], ac
    add  1, ac
    ld   ac, [0x26]
    ld   [0x32], ac
    dec
    ld   ac, [0x32]
    bne  pt0
    ; write the byte to 1 screen row(s)
    ld   [0x35], ac
    add  [0x34], y
    ld   [0x33], x
    ld   [0x30], ac
    ld   ac, [y,x]
    ; once per byte: check the line read for a new frame
    ld   ret_18, ac
    ld   ac, [0x43]
    ld   ret_18 >> 8, ac
    ld   ac, [0x44]
    ld   poll >> 8, y
    jmp  poll
ret_18:
    ; next byte column: cx0 += 8/256, video page += 2
    ld   [0x2E], ac
    add  8, ac
    ld   ac, [0x2E]
    bcc  cxd0
    ld   [0x2F], ac
    inc
    ld   ac, [0x2F]
cxd0:
    ld   [0x35], ac
    add  2, ac
    ld   ac, [0x35]
    ld   [0x36], ac
    dec
    ld   ac, [0x36]
    beq  rd0
    ld   col0 >> 8, y
    jmp  col0
rd0:
    ld   rdone0 >> 8, y
    jmp  rdone0
pdone0:
    ld   [0x3C], y
    jmp  [0x3B]

#addr 0x0500
rdone0:
    ; the row is done: show its 1 screen row(s), mode byte 00
    ld   [0x34], ac
    add  0x5A, y
    ld   [0x33], ac
    add  0, x
    ld   0x00, [y,x]
    ; next row: rowy:rowx += 1, cy += 1/256
    add  1, ac
    ld   ac, [0x33]
    bcc  rxd0
    ld   [0x34], ac
    inc
    ld   ac, [0x34]
rxd0:
    ld   [0x28], ac
    add  1, ac
    ld   ac, [0x28]
    bcc  cyd0
    ld   [0x29], ac
    inc
    ld   ac, [0x29]
cyd0:
    ; done after 480 rows: rowy:rowx = 0x200
    ld   [0x34], ac
    sub  2, ac
    beq  pd0
    ld   row0 >> 8, y
    jmp  row0
pd0:
    ld   pdone0 >> 8, y
    jmp  pdone0

#addr 0x0600
pass1:
    ; 2 bpp: 4 points per byte, 2 x 2 pixels per point
    ld   [0x2C], ac
    ld   ac, [0x3B]
    ld   [0x2D], ac
    ld   ac, [0x3C]
    ld   ret_19, ac
    ld   ac, [0x2C]
    ld   ret_19 >> 8, ac
    ld   ac, [0x2D]
    ld   clear >> 8, y
    jmp  clear
ret_19:
