    jmp  tstart
ret_20:
    ld   0x40, ac
    ld   ac, [0x2B]
    ; row by row, top to bottom: every row starts blanked (clear) and
    ; is shown when its points are done, so the video does not stall
    ; the CPU on the rows still to come
    ld   0x20, ac
    ld   ac, [0x33]
    ld   0x00, ac
    ld   ac, [0x34]
    ; cy = -240/256 = (hi -1, lo 16)
    ld   0xFF, ac
    ld   ac, [0x29]
    ld   0x10, ac
    ld   ac, [0x28]
row1:
    ld   0x62, ac
    ld   ac, [0x35]
    ; cx = -2.0 = -512 = (hi -2, lo 0)
    ld   0xFE, ac
    ld   ac, [0x2F]
    ld   0x00, ac
    ld   ac, [0x2E]
    ld   0x4F, ac
    ld   ac, [0x36]
col1:
    ld   [0x2E], ac
    ld   ac, [0x26]
    ld   [0x2F], ac
    ld   ac, [0x27]
    ld   0x00, ac
    ld   ac, [0x30]
    ld   0x04, ac
    ld   ac, [0x32]
pt1:
    ld   ret_21, ac
    ld   ac, [0x2C]
    ld   ret_21 >> 8, ac
    ld   ac, [0x2D]
    ld   kernel >> 8, y
    jmp  kernel
ret_21:
    ld   ac, [0x31]
    ld   [0x30], ac
    shr  ac
    shr  ac
    or   [0x31], ac
    ld   ac, [0x30]
    ; next point: cx lo is a multiple of 8 plus < 8, never carries
    ld   [0x26], ac
    add  2, ac
    ld   ac, [0x26]
    ld   [0x32], ac
    dec
    ld   ac, [0x32]
    bne  pt1
    ; write the byte to 2 screen row(s)
    ld   [0x35], ac
    add  [0x34], y
    ld   [0x33], x
    ld   [0x30], ac
    ld   ac, [y,x]
    ld   [0x33], ac
    add  1, x
    ld   [0x30], ac
    ld   ac, [y,x]
    ; once per byte: check the line read for a new frame
    ld   ret_22, ac
    ld   ac, [0x43]
    ld   ret_22 >> 8, ac
    ld   ac, [0x44]
    ld   poll >> 8, y
    jmp  poll
ret_22:
    ; next byte column: cx0 += 8/256, video page += 2
    ld   [0x2E], ac
    add  8, ac
    ld   ac, [0x2E]
    bcc  cxd1
    ld   [0x2F], ac
    inc
    ld   ac, [0x2F]
cxd1:
    ld   [0x35], ac
    add  2, ac
    ld   ac, [0x35]
    ld   [0x36], ac
    dec
    ld   ac, [0x36]
    beq  rd1
    ld   col1 >> 8, y
    jmp  col1
rd1:
    ld   rdone1 >> 8, y
    jmp  rdone1
pdone1:
    ld   [0x3C], y
    jmp  [0x3B]

#addr 0x0700
rdone1:
    ; the row is done: show its 2 screen row(s), mode byte 01
    ld   [0x34], ac
    add  0x5A, y
    ld   [0x33], ac
    add  0, x
    ld   0x01, [y,x]
    add  1, x
    ld   0x01, [y,x]
    ; next row: rowy:rowx += 2, cy += 2/256
    add  2, ac
    ld   ac, [0x33]
    bcc  rxd1
    ld   [0x34], ac
    inc
    ld   ac, [0x34]
rxd1:
    ld   [0x28], ac
    add  2, ac
    ld   ac, [0x28]
    bcc  cyd1
    ld   [0x29], ac
    inc
    ld   ac, [0x29]
cyd1:
    ; done after 480 rows: rowy:rowx = 0x200
    ld   [0x34], ac
    sub  2, ac
    beq  pd1
    ld   row1 >> 8, y
    jmp  row1
pd1:
    ld   pdone1 >> 8, y
    jmp  pdone1

#addr 0x0800
pass2:
    ; 4 bpp: 2 points per byte, 4 x 4 pixels per point
    ld   [0x2C], ac
    ld   ac, [0x3B]
    ld   [0x2D], ac
    ld   ac, [0x3C]
    ld   ret_23, ac
    ld   ac, [0x2C]
    ld   ret_23 >> 8, ac
    ld   ac, [0x2D]
    ld   clear >> 8, y
    jmp  clear
ret_23:
    ld   ret_24, ac
    ld   ac, [0x2C]
    ld   ret_24 >> 8, ac
    ld   ac, [0x2D]
    ld   tstart >> 8, y
    jmp  tstart
ret_24:
    ld   0x80, ac
    ld   ac, [0x2B]
    ; row by row, top to bottom: every row starts blanked (clear) and
    ; is shown when its points are done, so the video does not stall
    ; the CPU on the rows still to come
    ld   0x20, ac
    ld   ac, [0x33]
    ld   0x00, ac
    ld   ac, [0x34]
    ; cy = -240/256 = (hi -1, lo 16)
    ld   0xFF, ac
    ld   ac, [0x29]
    ld   0x10, ac
    ld   ac, [0x28]
row2:
    ld   0x62, ac
    ld   ac, [0x35]
    ; cx = -2.0 = -512 = (hi -2, lo 0)
    ld   0xFE, ac
    ld   ac, [0x2F]
    ld   0x00, ac
    ld   ac, [0x2E]
    ld   0x4F, ac
    ld   ac, [0x36]
col2:
    ld   [0x2E], ac
    ld   ac, [0x26]
    ld   [0x2F], ac
    ld   ac, [0x27]
    ld   0x00, ac
    ld   ac, [0x30]
    ld   0x02, ac
    ld   ac, [0x32]
pt2:
    ld   ret_25, ac
    ld   ac, [0x2C]
    ld   ret_25 >> 8, ac
    ld   ac, [0x2D]
    ld   kernel >> 8, y
    jmp  kernel
ret_25:
    ld   ac, [0x31]
    ld   [0x30], ac
    shr  ac
    shr  ac
    shr  ac
    shr  ac
    or   [0x31], ac
    ld   ac, [0x30]
    ; next point: cx lo is a multiple of 8 plus < 8, never carries
    ld   [0x26], ac
    add  4, ac
    ld   ac, [0x26]
    ld   [0x32], ac
    dec
    ld   ac, [0x32]
    bne  pt2
    ; write the byte to 4 screen row(s)
    ld   [0x35], ac
    add  [0x34], y
    ld   [0x33], x
    ld   [0x30], ac
    ld   ac, [y,x]
    ld   [0x33], ac
    add  1, x
    ld   [0x30], ac
    ld   ac, [y,x]
    ld   [0x33], ac
    add  2, x
    ld   [0x30], ac
    ld   ac, [y,x]
    ld   [0x33], ac
    add  3, x
    ld   [0x30], ac
    ld   ac, [y,x]
    ; once per byte: check the line read for a new frame
    ld   ret_26, ac
    ld   ac, [0x43]
    ld   ret_26 >> 8, ac
    ld   ac, [0x44]
    ld   poll >> 8, y
    jmp  poll
ret_26:
    ; next byte column: cx0 += 8/256, video page += 2
    ld   [0x2E], ac
    add  8, ac
    ld   ac, [0x2E]
    bcc  cxd2
    ld   [0x2F], ac
    inc
    ld   ac, [0x2F]
cxd2:
    ld   [0x35], ac
