ret_29:
    ld   ac, [0x31]
    ld   ac, [0x30]
    ; write the byte to 8 screen row(s)
    ld   [0x35], ac
    add  [0x34], y
    ld   [0x33], x
    ld   [0x30], ac
    ld   ac, [y,x]
    ld   [0x33], ac
    add  1, x
    ld   [0x30], ac
    ld   ac, [y,x]
    ld   [0x33], ac
    add  2, x
    ld   [0x30], ac
    ld   ac, [y,x]
    ld   [0x33], ac
    add  3, x
    ld   [0x30], ac
    ld   ac, [y,x]
    ld   [0x33], ac
    add  4, x
    ld   [0x30], ac
    ld   ac, [y,x]
    ld   [0x33], ac
    add  5, x
    ld   [0x30], ac
    ld   ac, [y,x]
    ld   [0x33], ac
    add  6, x
    ld   [0x30], ac
    ld   ac, [y,x]
    ld   [0x33], ac
    add  7, x
    ld   [0x30], ac
    ld   ac, [y,x]
    ; once per byte: check the line read for a new frame
    ld   ret_30, ac
    ld   ac, [0x43]
    ld   ret_30 >> 8, ac
    ld   ac, [0x44]
    ld   poll >> 8, y
    jmp  poll
ret_30:
    ; next byte column: cx0 += 8/256, video page += 2
    ld   [0x2E], ac
    add  8, ac
    ld   ac, [0x2E]
    bcc  cxd3
    ld   [0x2F], ac
    inc
    ld   ac, [0x2F]
cxd3:
    ld   [0x35], ac
    add  2, ac
    ld   ac, [0x35]
    ld   [0x36], ac
    dec
    ld   ac, [0x36]
    beq  rd3
    ld   col3 >> 8, y
    jmp  col3
rd3:
    ld   rdone3 >> 8, y
    jmp  rdone3
pdone3:
    ld   [0x3C], y
    jmp  [0x3B]

#addr 0x0B00
rdone3:
    ; the row is done: show its 8 screen row(s), mode byte 03
    ld   [0x34], ac
    add  0x5A, y
    ld   [0x33], ac
    add  0, x
    ld   0x03, [y,x]
    add  1, x
    ld   0x03, [y,x]
    add  2, x
    ld   0x03, [y,x]
    add  3, x
    ld   0x03, [y,x]
    add  4, x
    ld   0x03, [y,x]
    add  5, x
    ld   0x03, [y,x]
    add  6, x
    ld   0x03, [y,x]
    add  7, x
    ld   0x03, [y,x]
    ; next row: rowy:rowx += 8, cy += 8/256
    add  8, ac
    ld   ac, [0x33]
    bcc  rxd3
    ld   [0x34], ac
    inc
    ld   ac, [0x34]
rxd3:
    ld   [0x28], ac
    add  8, ac
    ld   ac, [0x28]
    bcc  cyd3
    ld   [0x29], ac
    inc
    ld   ac, [0x29]
cyd3:
    ; done after 480 rows: rowy:rowx = 0x200
    ld   [0x34], ac
    sub  2, ac
    beq  pd3
    ld   row3 >> 8, y
    jmp  row3
pd3:
    ld   pdone3 >> 8, y
    jmp  pdone3

#addr 0x0C00
poll:
    ; read the line read (V9:V2, 124-255) and add one frame to the timer
    ; when it went down.  cur - last - 96 >= 0 means it wrapped, as long as
    ; polls are less than 95 steps (380 lines) apart.  Uses y and x.
    ; The menu hook first (Esc, time up: menu_hook.py).
    ld   ret_31, ac
    ld   ac, [0xE8]
    ld   ret_31 >> 8, ac
    ld   ac, [0xE9]
    ld   hk_poll >> 8, y
    jmp  hk_poll
ret_31:
    ld   0x50, y
    ld   [y,x], ac
    ld   ac, [0x3D]
    sub  [0x3E], ac
    sub  96, ac
    blt  pnw
    ld   0x01, ac
    ld   ac, [0x3F]
    ld   0x10, ac
    ld   ac, [0x40]
    ld   ret_32, ac
    ld   ac, [0x45]
    ld   ret_32 >> 8, ac
    ld   ac, [0x46]
    ld   dadd >> 8, y
    jmp  dadd
ret_32:
pnw:
    ld   [0x3D], ac
    ld   ac, [0x3E]
    ld   [0x44], y
    jmp  [0x43]

#addr 0x0D00
hk_poll:
    ld 0x5D, y
    ld 0x00, x
    ld [y,x], ac
    xor 0x4D, ac
    bne hkp_ret
    ld 0x01, x
    ld [y,x], ac
    xor 0x4E, ac
    bne hkp_ret
    ld 0x02, x
    ld [y,x], ac
    xor 0x55, ac
    bne hkp_ret
    ld 0x50, y    ; line read (V9:V2)
    ld [y,x], ac
    ld 0x5D, y
    ld 0x0A, x
    ld ac, [y,x]
    ld 0x06, x
    sub [y,x], ac    ; cur - last - 96 >= 0: a new frame
    sub 96, ac
    ld 0x0A, x
    blt hkp_same
    ld [y,x], ac
    ld 0x06, x
    ld ac, [y,x]
    ld 0x52, y    ; a byte from the PS/2 keyboard (D7 = 0)?
    ld 0x03, x
    ld [y,x], ac
    blt hkp_time
    bra hkp_byte
hkp_time:
    ld 0x5D, y
    ld 0x03, x
    ld [y,x], ac
    bne hkp_ret    ; picked from the menu: no time limit
    ld 0x04, x
    ld [y,x], ac
    dec
    ld ac, [y,x]
    bcc hkp_ret    ; no borrow
    ld 0x05, x
    ld [y,x], ac
    dec
    ld ac, [y,x]
    blt hkp_next    ; below 0: time up
    bra hkp_ret
hkp_same:
    ld [y,x], ac
    ld 0x06, x
    ld ac, [y,x]
hkp_ret:
    ld [0xE9], y
    jmp [0xE8]
hkp_byte:
    ld 0x02, x
    ld [y,x], ac    ; the byte
    ld 0xFB, [y,x]    ; re-arm the receiver, the keyboard still free
    ld 0x5D, y
    ld 0x0A, x
    ld ac, [y,x]
    xor 0x76, ac
    bne hkp_nesc
    ld 0x10, x    ; F0 76 is Esc let go, not pressed
    ld [y,x], ac
    xor 0xF0, ac
    bne hkp_esc
hkp_nesc:
    ld 0x0A, x
    ld [y,x], ac
    ld 0x10, x
    ld ac, [y,x]
    bra hkp_time
hkp_esc:
    ld 1, ac
    bra hkp_go
hkp_next:
    ld 2, ac
hkp_go:
    ld 0x5D, y
    ld 0x09, x
    ld ac, [y,x]
    jmp 0x20    ; the menu's exit code (RAM x5D20)

#addr 0x0E00
hk_done:
    ld 0x5D, y
    ld 0x00, x
    ld [y,x], ac
    xor 0x4D, ac
    bne hkd_ret
    ld 0x01, x
    ld [y,x], ac
    xor 0x4E, ac
    bne hkd_ret
    ld 0x02, x
    ld [y,x], ac
    xor 0x55, ac
    bne hkd_ret
    ld 0x03, x
    ld [y,x], ac
    beq hkd_next    ; rotating: next program
hkd_ret:
    ld [0xE9], y
    jmp [0xE8]
hkd_next:
    ld 2, ac
    ld 0x09, x
    ld ac, [y,x]
    jmp 0x20    ; the menu's exit code (RAM x5D20)
hk_hold:
    ld 0x5D, y
    ld 0x00, x
    ld [y,x], ac
    xor 0x4D, ac
    bne hkd_ret
    ld 0x01, x
    ld [y,x], ac
    xor 0x4E, ac
    bne hkd_ret
    ld 0x02, x
    ld [y,x], ac
    xor 0x55, ac
    bne hkd_ret
    ld 0x03, x
    ld [y,x], ac
    bne hkd_ret    ; picked from the menu: no time limit
    ld 0x04, x    ; MB_LEFT - MB_HOLD < 0: leaves sooner anyway
    ld [y,x], ac
    ld 0x0B, x
    sub [y,x], ac
    ld 0x05, x
    ld [y,x], ac
    bcc hkd_nb
    sub 1, ac
hkd_nb:
    ld 0x0C, x
    sub [y,x], ac
    blt hkd_ret
    ld 0x0B, x    ; MB_LEFT = MB_HOLD
    ld [y,x], ac
    ld 0x04, x
    ld ac, [y,x]
    ld 0x0C, x
    ld [y,x], ac
    ld 0x05, x
    ld ac, [y,x]
    bra hkd_ret

#addr 0x0F00
dadd:
    ; timer digits at 0x50 += addend digits at 0x50 + [doff], decimal
    clr  ac
    ld   ac, [0x41]
    ld   ac, [0x4F]
dl:
    ld   [0x4F], ac
    add  0x50, x
    ld   [x], ac
    add  [0x41], ac
    ld   ac, [0x42]
    ld   [0x4F], ac
    add  [0x40], ac
    add  0x50, x
    ld   [x], ac
    add  [0x42], ac
    ld   ac, [0x42]
    ld   [0x4F], ac
    add  0x50, x
    ld   [0x42], ac
    sub  10, ac
    blt  dlt
    ld   ac, [x]
    ld   1, ac
    bra  dn
dlt:
    ld   [0x42], ac
    ld   ac, [x]
    clr  ac
dn:
    ld   ac, [0x41]
    ld   [0x4F], ac
    inc
    ld   ac, [0x4F]
    sub  9, ac
    bne  dl
    ld   [0x46], y
    jmp  [0x45]

#addr 0x1000
tstart:
    ; start the timer at the top of a frame: wait for the line read to wrap
    ld   ret_33, ac
    ld   ac, [0x43]
    ld   ret_33 >> 8, ac
    ld   ac, [0x44]
    ld   poll >> 8, y
    jmp  poll
ret_33:
sync:
    ld   0x00, ac
    ld   ac, [0x3F]
    ld   ret_34, ac
    ld   ac, [0x43]
    ld   ret_34 >> 8, ac
    ld   ac, [0x44]
    ld   poll >> 8, y
    jmp  poll
ret_34:
    ld   [0x3F], ac
    beq  sync
    ld   ret_35, ac
    ld   ac, [0x43]
    ld   ret_35 >> 8, ac
    ld   ac, [0x44]
    ld   tclear >> 8, y
    jmp  tclear
ret_35:
    ld   [0x2D], y
    jmp  [0x2C]

#addr 0x1100
tclear:
    ; timer = 0, frame addend = 16800 us, step addend = 128 us
    ld   0x28, ac
tcl:
    add  0x50, x
    ld   0x00, [x]
    sub  1, ac
    bcc  tcl
    ld   8, ac
    ld   ac, [0x62]
    ld   6, ac
    ld   ac, [0x63]
    ld   1, ac
    ld   ac, [0x64]
    ld   8, ac
    ld   ac, [0x70]
    ld   2, ac
    ld   ac, [0x71]
    ld   1, ac
    ld   ac, [0x72]
    ld   [0x44], y
    jmp  [0x43]

#addr 0x1200
tshow:
    ; stop the timer: whole frames are counted, add the 128 us steps since
    ; the top of this frame
    ld   ret_36, ac
    ld   ac, [0x43]
    ld   ret_36 >> 8, ac
    ld   ac, [0x44]
    ld   poll >> 8, y
    jmp  poll
ret_36:
    ld   [0x3E], ac
    sub  124, ac
    ld   ac, [0x38]
    ld   0x20, ac
    ld   ac, [0x40]
part:
    ld   [0x38], ac
    beq  pdn
    dec
    ld   ac, [0x38]
    ld   ret_37, ac
    ld   ac, [0x45]
    ld   ret_37 >> 8, ac
    ld   ac, [0x46]
    ld   dadd >> 8, y
    jmp  dadd
ret_37:
    bra  part
pdn:
    ; a black 1 bpp band, screen rows 232-247: mode bytes 0, pixels 0
    ld   0x61, ac
    ld   ac, [0x38]
bnd:
    ld   [0x38], y
    ld   15, ac
bndr:
    add  0x08, x
    ld   0x00, [y,x]
    sub  1, ac
    bcc  bndr
    ld   [0x38], ac
    add  2, ac
    ld   ac, [0x38]
    sub  0x01, ac
    bne  bnd
    ld   0x5B, y
    ld   15, ac
bndm:
    add  0x08, x
    ld   0x00, [y,x]
    sub  1, ac
    bcc  bndm
    ld   tshow2 >> 8, y
    jmp  tshow2

#addr 0x1300
tshow2:
    ; "SSS.SSS s", leading zeros of the seconds as spaces
    ld   0xA9, ac
    ld   ac, [0x4C]
    ld   0x0C, ac
    ld   ac, [0x4D]
    ld   [0x58], ac
    bne  sh1
    ld   11, ac
    ld   ac, [0x58]
    ld   [0x57], ac
    bne  sh1
    ld   11, ac
    ld   ac, [0x57]
sh1:
    ld   0x58, ac
    ld   ac, [0x49]
shlp:
    ld   [0x49], x
    ld   [x], ac
    ld   ac, [0x4E]
    ld   ret_38, ac
    ld   ac, [0x47]
    ld   ret_38 >> 8, ac
    ld   ac, [0x48]
    ld   gdraw >> 8, y
    jmp  gdraw
ret_38:
    ld   [0x49], ac
    sub  0x56, ac
    bne  shnd
    ld   0x0A, ac
    ld   ac, [0x4E]
    ld   ret_39, ac
    ld   ac, [0x47]
    ld   ret_39 >> 8, ac
    ld   ac, [0x48]
    ld   gdraw >> 8, y
    jmp  gdraw
ret_39:
shnd:
    ld   [0x49], ac
    dec
    ld   ac, [0x49]
    sub  0x52, ac
    bne  shlp
    ld   0x0B, ac
    ld   ac, [0x4E]
    ld   ret_40, ac
    ld   ac, [0x47]
    ld   ret_40 >> 8, ac
    ld   ac, [0x48]
    ld   gdraw >> 8, y
    jmp  gdraw
ret_40:
    ld   0x0C, ac
    ld   ac, [0x4E]
    ld   ret_41, ac
    ld   ac, [0x47]
    ld   ret_41 >> 8, ac
    ld   ac, [0x48]
    ld   gdraw >> 8, y
    jmp  gdraw
ret_41:
    ld   [0x2D], y
    jmp  [0x2C]

#addr 0x1400
gdraw:
    ; draw glyph [dig] at page [cpg], row byte [crow]; then cpg += 2
    ld   [0x4E], ac
    shl
    shl
    shl
    add  0x80, ac
    ld   ac, [0x4A]
    ld   [0x4D], ac
    ld   ac, [0x4B]
    ld   [0x4A], ac
    add  0, x
    ld   [x], ac
    ld   ac, [0x38]
    ld   [0x4B], ac
    add  0, x
    ld   [0x4C], y
    ld   [0x38], ac
    ld   ac, [y,x]
    ld   [0x4A], ac
    add  1, x
    ld   [x], ac
    ld   ac, [0x38]
    ld   [0x4B], ac
    add  1, x
    ld   [0x4C], y
    ld   [0x38], ac
    ld   ac, [y,x]
    ld   [0x4A], ac
    add  2, x
    ld   [x], ac
    ld   ac, [0x38]
    ld   [0x4B], ac
    add  2, x
    ld   [0x4C], y
    ld   [0x38], ac
    ld   ac, [y,x]
    ld   [0x4A], ac
    add  3, x
    ld   [x], ac
    ld   ac, [0x38]
    ld   [0x4B], ac
    add  3, x
    ld   [0x4C], y
    ld   [0x38], ac
    ld   ac, [y,x]
    ld   [0x4A], ac
    add  4, x
    ld   [x], ac
    ld   ac, [0x38]
    ld   [0x4B], ac
    add  4, x
    ld   [0x4C], y
    ld   [0x38], ac
    ld   ac, [y,x]
    ld   [0x4A], ac
    add  5, x
    ld   [x], ac
    ld   ac, [0x38]
    ld   [0x4B], ac
    add  5, x
    ld   [0x4C], y
    ld   [0x38], ac
    ld   ac, [y,x]
    ld   [0x4A], ac
    add  6, x
    ld   [x], ac
    ld   ac, [0x38]
    ld   [0x4B], ac
    add  6, x
    ld   [0x4C], y
    ld   [0x38], ac
    ld   ac, [y,x]
    ld   [0x4A], ac
    add  7, x
    ld   [x], ac
    ld   ac, [0x38]
    ld   [0x4B], ac
    add  7, x
    ld   [0x4C], y
    ld   [0x38], ac
    ld   ac, [y,x]
    ld   [0x4C], ac
    add  2, ac
    ld   ac, [0x4C]
    ld   [0x48], y
    jmp  [0x47]

#addr 0x1500
kernel:
    ; in: cx, cy, coff.  out: AC = color for this mode.  returns to [reth, ret]
    clr  ac
    ld   ac, [0x10]
    ld   ac, [0x11]
    ld   ac, [0x13]
    ld   ac, [0x14]
    ld   ac, [0x12]
    ld   ac, [0x15]
    ld   0x20, ac
    ld   ac, [0x2A]
iter:
    ; x*x, y*y
    ld   [0x10], x
    ld   [0x11], ac
    add  0x20, y
    ld   [y,x], ac
    ld   ac, [0x16]
    ld   [0x11], ac
    add  0x24, y
    ld   [y,x], ac
    ld   ac, [0x17]
    ld   [0x13], x
    ld   [0x14], ac
    add  0x20, y
    ld   [y,x], ac
    ld   ac, [0x18]
    ld   [0x14], ac
    add  0x24, y
    ld   [y,x], ac
    ld   ac, [0x19]
    ; t = x*x + y*y, escape if t >= 4.0 (hi >= 4)
    ld   [0x16], ac
    add  [0x18], ac
    ld   ac, [0x1A]
    ld   [0x17], ac
    bcc  nc_42
    inc
nc_42:
    add  [0x19], ac
    ld   ac, [0x1B]
    sub  4, ac
    bcc  escape
    ; x' = x*x - y*y + cx
    ld   [0x16], ac
    sub  [0x18], ac
    ld   ac, [0x1C]
    ld   [0x17], ac
    bcc  nb_43
    dec
nb_43:
    sub  [0x19], ac
    ld   ac, [0x1D]
    ld   [0x1C], ac
    add  [0x26], ac
    ld   ac, [0x1E]
    ld   [0x1D], ac
    bcc  nc_44
    inc
nc_44:
    add  [0x27], ac
    ld   ac, [0x1F]
    ld   kernel2 >> 8, y
    jmp  kernel2
escape:
    ; color from the iterations left (0 = never escaped)
    ld   [0x2A], ac
    add  [0x2B], ac
    ld   ac, x
    ld   0x1F, y
    ld   [y,x], ac
    ld   [0x2D], y
    jmp  [0x2C]

#addr 0x1600
kernel2:
    ; s = |x + y|
    ld   [0x12], ac
    xor  [0x15], ac
    bne  sdiff
    ld   [0x10], ac
    add  [0x13], ac
    ld   ac, [0x22]
    ld   [0x11], ac
    bcc  nc_45
    inc
nc_45:
    add  [0x14], ac
    ld   ac, [0x23]
    bra  sdone
sdiff:
    ld   [0x10], ac
    sub  [0x13], ac
    ld   ac, [0x22]
    ld   [0x11], ac
    bcc  nb_46
    dec
nb_46:
    sub  [0x14], ac
    ld   ac, [0x23]
    blt  ge_47
    bra  sdone
ge_47:
    ld   [0x13], ac
    sub  [0x10], ac
    ld   ac, [0x22]
    ld   [0x14], ac
    bcc  nb_48
    dec
nb_48:
    sub  [0x11], ac
    ld   ac, [0x23]
sdone:
    ld   [0x22], x
    ld   [0x23], ac
    add  0x20, y
    ld   [y,x], ac
    ld   ac, [0x24]
    ld   [0x23], ac
    add  0x24, y
    ld   [y,x], ac
    ld   ac, [0x25]
    ; y' = s*s - t + cy  (= 2xy + cy)
    ld   [0x24], ac
    sub  [0x1A], ac
    ld   ac, [0x20]
    ld   [0x25], ac
    bcc  nb_49
    dec
nb_49:
    sub  [0x1B], ac
    ld   ac, [0x21]
    ld   [0x20], ac
    add  [0x28], ac
    ld   ac, [0x20]
    ld   [0x21], ac
    bcc  nc_50
    inc
nc_50:
    add  [0x29], ac
    ld   ac, [0x21]
    ld   kernel3 >> 8, y
    jmp  kernel3

#addr 0x1700
kernel3:
    ; back to magnitude + sign, escape if |x'| or |y'| >= 2
    ld   [0x1F], ac
    blt  neg_51
    sub  2, ac
    bcc  esc3
    ld   [0x1E], ac
    ld   ac, [0x10]
    ld   [0x1F], ac
    ld   ac, [0x11]
    clr  ac
    ld   ac, [0x12]
    bra  sm_53
neg_51:
    clr  ac                    ; magnitude = 0 - value
    sub  [0x1E], ac
    ld   ac, [0x10]
    clr  ac
    bcc  nb_52
    dec
nb_52:
    sub  [0x1F], ac
    ld   ac, [0x11]
    sub  2, ac
    bcc  esc3
    ld   1, ac
    ld   ac, [0x12]
sm_53:
    ld   [0x21], ac
    blt  neg_54
    sub  2, ac
    bcc  esc3
    ld   [0x20], ac
    ld   ac, [0x13]
    ld   [0x21], ac
    ld   ac, [0x14]
    clr  ac
    ld   ac, [0x15]
    bra  sm_56
neg_54:
    clr  ac                    ; magnitude = 0 - value
    sub  [0x20], ac
    ld   ac, [0x13]
    clr  ac
    bcc  nb_55
    dec
nb_55:
    sub  [0x21], ac
    ld   ac, [0x14]
    sub  2, ac
    bcc  esc3
    ld   1, ac
    ld   ac, [0x15]
sm_56:
    ld   [0x2A], ac
    dec
    ld   ac, [0x2A]
    beq  esc3                 ; never escaped: it = 0 -> black
    ld   iter >> 8, y
    jmp  iter
esc3:
    ld   escape >> 8, y
    jmp  escape

